import json, re
from collections import defaultdict

# Count order_items queries per request_id, bucketed by minute, before vs after deploy
before = defaultdict(int)   # 14:20-14:30
after  = defaultdict(int)   # 14:32-14:40
pat = "SELECT * FROM order_items WHERE order_id = ?"

with open("app.log") as f:
    for line in f:
        if pat not in line:
            continue
        try:
            r = json.loads(line)
        except: 
            continue
        if r.get("service") != "checkout": 
            continue
        ts = r["ts"]; mn = ts[11:16]; rid = r.get("request_id")
        if "14:20" <= mn <= "14:30":
            before[rid]+=1
        elif "14:32" <= mn <= "14:40":
            after[rid]+=1

def summ(d,label):
    if not d:
        print(label, "no requests with that query"); return
    vals=list(d.values())
    print(f"{label}: {len(d)} requests, queries/req min={min(vals)} max={max(vals)} avg={sum(vals)/len(vals):.1f}")

summ(before,"BEFORE deploy (14:20-14:30)")
summ(after ,"AFTER  deploy (14:32-14:40)")
EOF"
}
